// Phase 1: Timing-Safe HMAC-SHA256 Verification & Bi-Directional Replay Window (+/- 300s)
const crypto = require('crypto');

const headers = $node['Webhook_ACARS_Fault_Intake'].json.headers || {};
const body = $node['Webhook_ACARS_Fault_Intake'].json.body || {};
const rawPayload = typeof body === 'string' ? body : JSON.stringify(body);

// 1. Resolve HMAC Secret from environment or fallback
const hmacSecret = $env['AERO_MRO_HMAC_SECRET_2026'] || 'AERO_MRO_HMAC_SECRET_2026';

// 2. Validate HMAC Signature
const inboundSig = headers['x-mro-signature-sha256'] || headers['X-MRO-Signature-SHA256'] || '';
const computedSig = crypto.createHmac('sha256', hmacSecret).update(rawPayload).digest('hex');

let isSignatureValid = false;
try {
  const bufInbound = Buffer.from(inboundSig, 'hex');
  const bufComputed = Buffer.from(computedSig, 'hex');
  if (bufInbound.length === bufComputed.length) {
    isSignatureValid = crypto.timingSafeEqual(bufInbound, bufComputed);
  }
} catch (e) {
  isSignatureValid = false;
}

if (!isSignatureValid) {
  return [{ json: { decision: 'REJECT_401', error: 'HMAC_SIGNATURE_MISMATCH', statusCode: 401 } }];
}

// 3. Bi-Directional Replay Window (+/- 300s actively enforced without bypass)
const inboundTimestampStr = headers['x-mro-timestamp'] || headers['X-MRO-Timestamp'] || body.faultDetectedUtc || '';
const nowMs = Date.now();
const inboundMs = inboundTimestampStr ? new Date(inboundTimestampStr).getTime() : 0;
const driftMs = Math.abs(nowMs - inboundMs);

if (!inboundTimestampStr || isNaN(inboundMs) || driftMs > 300000) {
  return [{ json: { decision: 'REJECT_403', error: 'REPLAY_WINDOW_VIOLATION', driftMs, statusCode: 403 } }];
}

return [{
  json: {
    decision: 'ACCEPT_202',
    statusCode: 202,
    rawPayload: body,
    faultId: body.faultId,
    aircraftTailNumber: body.aircraftTailNumber,
    ataChapterCode: body.ataChapterCode,
    partNumber: body.partNumber,
    partSerialNumber: body.partSerialNumber,
    gateAssignmentId: body.gateAssignmentId,
    inspectorPhone: body.inspectorPhone,
    inspectorEmail: body.inspectorEmail,
    faultDetectedUtc: body.faultDetectedUtc,
    overrideChecksum: body.overrideChecksum,
    simulatePrimary503: body.simulatePrimary503,
    simulateGate400: body.simulateGate400
  }
}];

// Phase 2: Static State Mutex Deduplication Cache
const crypto = require('crypto');
const body = $json;

// Compute deterministic SHA-256 fingerprint from faultId + aircraftTailNumber
const key = `${body.faultId}_${body.aircraftTailNumber}`;
const fingerprint = crypto.createHash('sha256').update(key).digest('hex');

const staticData = $getWorkflowStaticData('global');
staticData.seenFaults = staticData.seenFaults || {};

let isDuplicate = false;
if (staticData.seenFaults[fingerprint]) {
  isDuplicate = true;
} else {
  staticData.seenFaults[fingerprint] = Date.now();
  isDuplicate = false;
}

return [{
  json: {
    ...body,
    fingerprint,
    isDuplicate
  }
}];

